/* Pixel Classroom Stylesheet */

[hidden] {
  display: none !important;
}

:root {
  --color-bg: #22252c;
  --color-card-bg: #2d323b;
  --color-desk-wood: #8f563b;
  --color-desk-shadow: #5c3422;
  --color-desk-highlight: #df7126;
  --color-occupied-chair: #37946e;
  --color-occupied-shadow: #225a43;
  --color-text-main: #f4f4f4;
  --color-text-muted: #9badb7;
  --color-accent: #696a6a;
  --color-warning: #d77643;
  --font-family: 'Courier New', Courier, monospace, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.4;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.classroom-card {
  background-color: var(--color-card-bg);
  border: 4px solid #14161b;
  box-shadow: 0 0 0 4px #4a5462, 8px 8px 0px 4px #0c0d10;
  border-radius: 4px;
  width: 100%;
  max-width: 540px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.classroom-header {
  text-align: center;
  border-bottom: 4px dashed #4a5462;
  padding-bottom: 14px;
}

.classroom-title {
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #df7126;
  margin-bottom: 8px;
  text-shadow: 2px 2px #000000;
}

.counter-display {
  font-size: 1.1rem;
  font-weight: bold;
  color: #63c74d;
  background: #191c21;
  display: inline-block;
  padding: 6px 14px;
  border: 2px solid #323c4a;
}

.controls-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  font-weight: bold;
  text-transform: uppercase;
}

.input-group {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

#student-name-input {
  flex: 1 1 200px;
  background: #14161b;
  border: 2px solid #5c6977;
  color: #ffffff;
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 12px;
  border-radius: 0;
  outline: none;
}

#student-name-input:focus {
  border-color: #63c74d;
  box-shadow: 0 0 0 2px #37946e;
}

.pixel-btn {
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: bold;
  text-transform: uppercase;
  padding: 10px 16px;
  border: 2px solid #14161b;
  cursor: pointer;
  background: #4a5462;
  color: #ffffff;
  box-shadow: 3px 3px 0 #14161b;
  transition: transform 0.05s, box-shadow 0.05s;
}

.pixel-btn:hover {
  background: #5c6977;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 #14161b;
}

.pixel-btn:focus-visible {
  outline: 3px solid #63c74d;
  outline-offset: 2px;
}

.secondary-btn {
  background: #854c30;
}

.secondary-btn:hover {
  background: #a05b38;
}

.status-message {
  font-size: 0.85rem;
  min-height: 1.2rem;
  color: #d77643;
  font-weight: bold;
}

.grid-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.teacher-desk {
  width: 100%;
  display: flex;
  justify-content: center;
}

.teacher-board {
  background: #14161b;
  color: #8b9bb4;
  font-size: 0.85rem;
  letter-spacing: 1.5px;
  padding: 4px 16px;
  border: 2px solid #3a4454;
  text-align: center;
}

.desk-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  width: 100%;
}

.desk-btn {
  background-color: var(--color-desk-wood);
  border: 3px solid var(--color-desk-shadow);
  box-shadow: 3px 3px 0 #101216;
  aspect-ratio: 1 / 1;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 6px 4px;
  color: #fff;
  font-family: inherit;
  font-size: 0.8rem;
  position: relative;
  text-align: center;
  overflow: hidden;
  transition: transform 0.05s, background-color 0.1s;
}

.desk-btn:hover {
  background-color: var(--color-desk-highlight);
}

.desk-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 #101216;
}

.desk-btn:focus-visible {
  outline: 3px solid #63c74d;
  outline-offset: 2px;
}

.desk-btn.occupied {
  background-color: var(--color-occupied-chair);
  border-color: var(--color-occupied-shadow);
}

.desk-btn.occupied:hover {
  background-color: #d77643;
}

.desk-number {
  font-size: 0.75rem;
  color: #14161b;
  background: rgba(255, 255, 255, 0.4);
  padding: 1px 4px;
  align-self: flex-start;
  line-height: 1;
  font-weight: bold;
}

.student-tag {
  font-size: 0.75rem;
  line-height: 1.1;
  word-break: break-word;
  max-width: 100%;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-weight: bold;
}

.desk-status-text {
  font-size: 0.65rem;
  text-transform: uppercase;
  opacity: 0.85;
}

.classroom-footer {
  text-align: center;
  border-top: 2px dashed #4a5462;
  padding-top: 12px;
}

.hint-text {
  font-size: 0.8rem;
  color: var(--color-text-muted);
}

/* Responsive adjustments for narrow screens down to 360px */
@media (max-width: 480px) {
  body {
    padding: 8px;
  }

  .classroom-card {
    padding: 16px;
    gap: 16px;
  }

  .classroom-title {
    font-size: 1.3rem;
  }

  .desk-grid {
    gap: 8px;
  }

  .desk-btn {
    padding: 4px 2px;
  }

  .student-tag {
    font-size: 0.65rem;
  }

  .desk-number {
    font-size: 0.65rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_DESKS = 12; // 3 rows x 4 columns
  const desks = Array.from({ length: TOTAL_DESKS }, (_, i) => ({
    id: i,
    row: Math.floor(i / 4) + 1,
    col: (i % 4) + 1,
    studentName: null,
  }));

  const deskGridEl = document.getElementById('desk-grid');
  const seatCounterEl = document.getElementById('seat-counter');
  const studentNameInput = document.getElementById('student-name-input');
  const clearAllBtn = document.getElementById('clear-all-btn');
  const statusMsgEl = document.getElementById('status-msg');

  let statusTimeout = null;

  function setStatusMessage(msg, isAlert = false) {
    if (statusTimeout) {
      clearTimeout(statusTimeout);
    }
    statusMsgEl.textContent = msg;
    statusMsgEl.style.color = isAlert ? '#e74c3c' : '#63c74d';
    if (msg) {
      statusTimeout = setTimeout(() => {
        statusMsgEl.textContent = '';
      }, 3500);
    }
  }

  function updateCounter() {
    const filledCount = desks.filter(d => d.studentName !== null).length;
    seatCounterEl.textContent = `${filledCount} / ${TOTAL_DESKS} Seats Filled`;
  }

  function renderDesk(desk) {
    const deskBtn = document.createElement('button');
    deskBtn.type = 'button';
    deskBtn.className = 'desk-btn';
    deskBtn.id = `desk-${desk.id}`;
    deskBtn.dataset.index = desk.id;

    const deskNum = document.createElement('span');
    deskNum.className = 'desk-number';
    deskNum.textContent = `R${desk.row}C${desk.col}`;

    const studentTag = document.createElement('span');
    studentTag.className = 'student-tag';

    const deskStatus = document.createElement('span');
    deskStatus.className = 'desk-status-text';

    if (desk.studentName) {
      deskBtn.classList.add('occupied');
      deskBtn.setAttribute('aria-label', `Desk Row ${desk.row} Column ${desk.col}, Occupied by ${desk.studentName}. Click to vacate.`);
      studentTag.textContent = desk.studentName;
      deskStatus.textContent = '[Seated]';
    } else {
      deskBtn.classList.remove('occupied');
      deskBtn.setAttribute('aria-label', `Desk Row ${desk.row} Column ${desk.col}, Empty. Click to seat student.`);
      studentTag.textContent = '-';
      deskStatus.textContent = '[Empty]';
    }

    deskBtn.appendChild(deskNum);
    deskBtn.appendChild(studentTag);
    deskBtn.appendChild(deskStatus);

    return deskBtn;
  }

  function renderAllDesks() {
    deskGridEl.innerHTML = '';
    desks.forEach(desk => {
      deskGridEl.appendChild(renderDesk(desk));
    });
    updateCounter();
  }

  function handleDeskClick(index) {
    const desk = desks[index];
    if (!desk) return;

    if (desk.studentName !== null) {
      // Clicking seated desk clears it
      const previousName = desk.studentName;
      desk.studentName = null;
      renderAllDesks();
      setStatusMessage(`Cleared ${previousName} from R${desk.row}C${desk.col}.`);
    } else {
      // Clicking empty desk seats student if name is present
      const name = studentNameInput.value.trim();
      if (!name) {
        setStatusMessage('Please type a student name first!', true);
        studentNameInput.focus();
        return;
      }

      desk.studentName = name;
      studentNameInput.value = '';
      renderAllDesks();
      setStatusMessage(`Seated ${name} at R${desk.row}C${desk.col}.`);
      studentNameInput.focus();
    }
  }

  deskGridEl.addEventListener('click', (event) => {
    const button = event.target.closest('.desk-btn');
    if (!button) return;
    const index = parseInt(button.dataset.index, 10);
    handleDeskClick(index);
  });

  clearAllBtn.addEventListener('click', () => {
    const occupied = desks.some(d => d.studentName !== null);
    if (!occupied) {
      setStatusMessage('All desks are already empty.', false);
      return;
    }
    desks.forEach(desk => {
      desk.studentName = null;
    });
    renderAllDesks();
    setStatusMessage('All desks have been cleared.');
  });

  // Allow pressing Enter in student input to auto-seat in first empty desk
  studentNameInput.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      const name = studentNameInput.value.trim();
      if (!name) {
        setStatusMessage('Please type a student name first!', true);
        return;
      }
      const firstEmptyIndex = desks.findIndex(d => d.studentName === null);
      if (firstEmptyIndex === -1) {
        setStatusMessage('Classroom is full! Clear a desk first.', true);
        return;
      }
      handleDeskClick(firstEmptyIndex);
    }
  });

  // Initial render
  renderAllDesks();
});
